# Z1805: at (★)-failing primes, levels C ≤ Cmax: Ω(4Cp+1) vs Davenport lower bound D*(G)=1+Σ(n_i−1), G=(Z/4C)^×,
# and the subgroup generated by the factor classes (general position test). Compare with control primes.
import sys
from sympy import factorint, primerange, isprime
from sympy.ntheory import n_order
from math import gcd
def unit_group_invariants(m):
    # invariants of (Z/m)^x via cyclic components of prime powers, then merge to elementary p-parts
    from collections import defaultdict
    comps=[]
    for q,e in factorint(m).items():
        if q==2:
            if e==2: comps.append(2)
            elif e>=3: comps+= [2, 2**(e-2)]
        else: comps.append((q-1)*q**(e-1))
    # p-primary decomposition
    pp=defaultdict(list)
    for c in comps:
        for r,f in factorint(c).items(): pp[r].append(r**f)
    return pp
def Dstar(m):
    pp=unit_group_invariants(m); return 1+sum(x-1 for L in pp.values() for x in L)
def gen_subgroup_contains_minus1(m, gens):
    H={1}; frontier=[1]
    while frontier:
        x=frontier.pop(); 
        for g in gens:
            y=x*g%m
            if y not in H: H.add(y); frontier.append(y)
    return (m-1) in H, len(H)
Cmax=int(sys.argv[1])
fails=[409,577,5569,9601,23929,83449,102001,329617,712321,8813281]
def scan(p):
    big=0; bigH=0; cert=0
    for C in range(1,min(Cmax,(p+2)//4)+1):
        m=4*C; N=m*p+1; f=factorint(N)
        Om=sum(f.values())
        hasm1,_=gen_subgroup_contains_minus1(m,[q%m for q in f])
        if Om>=Dstar(m):
            big+=1
            if hasm1: bigH+=1
    return big,bigH
print("Cmax",Cmax)
for p in fails:
    print("fail",p, "levels with Ω≥D*:", *scan(p))
import random
random.seed(1)
for p in fails[:6]:
    q=p+random.randrange(100,1000)
    while not (isprime(q) and q%8==1): q+=1
    print("ctrl",q, "levels with Ω≥D*:", *scan(q))
print("details at failing primes: (C, Ω, D*, |<factor classes>|, φ(4C), factor classes mod 4C)")
from sympy import totient
for p in fails:
    for C in range(1,min(Cmax,(p+2)//4)+1):
        m=4*C; f=factorint(m*p+1); Om=sum(f.values())
        if Om>=Dstar(m):
            h,sz=gen_subgroup_contains_minus1(m,[q%m for q in f])
            print(p,(C,Om,Dstar(m),sz,int(totient(m)),sorted({q%m for q in f})))
